ALTER TABLE customers ADD (reward_points NUMBER DEFAULT 0 NOT NULL, cashback_balance NUMBER(15,2) DEFAULT 0 NOT NULL, credit_health_score NUMBER DEFAULT 700 NOT NULL);
ALTER TABLE monthly_statements ADD (due_date DATE, late_fee_applied NUMBER(1) DEFAULT 0 NOT NULL);
CREATE TABLE credit_score_events (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_id NUMBER, event_type VARCHAR2(50) NOT NULL, points NUMBER NOT NULL, event_date DATE NOT NULL, reference_key VARCHAR2(120), description VARCHAR2(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_score_customer FOREIGN KEY(customer_id) REFERENCES customers(id), CONSTRAINT fk_score_card FOREIGN KEY(card_id) REFERENCES credit_cards(id));
CREATE TABLE credit_limit_requests (id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL, card_id NUMBER NOT NULL, current_limit NUMBER(15,2) NOT NULL, requested_limit NUMBER(15,2) NOT NULL, reason VARCHAR2(500) NOT NULL, status VARCHAR2(20) NOT NULL, reviewed_by VARCHAR2(80), reviewed_at TIMESTAMP, review_comment VARCHAR2(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, CONSTRAINT fk_limit_customer FOREIGN KEY(customer_id) REFERENCES customers(id), CONSTRAINT fk_limit_card FOREIGN KEY(card_id) REFERENCES credit_cards(id));
CREATE INDEX idx_score_customer_date ON credit_score_events(customer_id,event_date); CREATE INDEX idx_limit_status ON credit_limit_requests(status);
